 static JSONObject request(NasClient client,boolean read,byte[] bytes)throws Exception{return client.apiRequest(API,read?"get":"create",2,read,Map.of(),bytes==null?null:"fixture.torrent",bytes,"torrent");}
 @Test public void blockedUploadDoesNotBlockVideoOrFolderRequest()throws Exception{try(Fixture f=new Fixture()){NasClient client=f.client();f.slowUpload=true;ExecutorService pool=Executors.newFixedThreadPool(3);try{Future<?> upload=pool.submit(()->request(client,false,new byte[]{1,2,3}));assertTrue(f.uploadEntered.await(3,TimeUnit.SECONDS));Future<byte[]> video=pool.submit(()->{try(NasClient.Stream stream=client.stream("/video/movie.mkv","bytes=0-2",false)){return stream.body.readAllBytes();}});assertArrayEquals(new byte[]{1,2,3},video.get(2,TimeUnit.SECONDS));assertEquals(0,pool.submit(()->client.call("SYNO.FileStation.List","list",Map.of()).getInt("total")).get(2,TimeUnit.SECONDS).intValue());assertFalse(upload.isDone());f.release.countDown();upload.get(3,TimeUnit.SECONDS);}finally{f.release.countDown();pool.shutdownNow();}}}
 @Test public void discoveryAlsoRunsWithoutBlockingVideo()throws Exception{try(Fixture f=new Fixture()){NasClient client=f.client();f.slowDiscovery=true;ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> query=pool.submit(()->request(client,true,null));assertTrue(f.discoveryEntered.await(3,TimeUnit.SECONDS));assertArrayEquals(new byte[]{1,2,3},pool.submit(()->client.readFile("/video/movie.mkv",100)).get(2,TimeUnit.SECONDS));assertFalse(query.isDone());f.release.countDown();query.get(3,TimeUnit.SECONDS);}finally{f.release.countDown();pool.shutdownNow();}}}
 @Test public void lostWriteResponseIsNotReplayedByClientOrHttpStack()throws Exception{for(byte[] data:new byte[][]{null,new byte[]{1}})try(Fixture f=new Fixture()){NasClient client=f.client();f.disconnectWrite=true;try{request(client,false,data);fail();}catch(IOException expected){assertTrue(expected.getMessage().startsWith("Nem érkezett biztos NAS-visszaigazolás"));}assertEquals(1,f.requests.get());}}
 @Test public void writeHttpFailureIsNotRetriedButReadFailureIs()throws Exception{try(Fixture f=new Fixture()){NasClient client=f.client();f.failWrite=true;try{request(client,false,new byte[]{1});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("nem ismételtem"));}assertEquals(1,f.requests.get());f.failRead=true;try{request(client,true,null);fail();}catch(IOException expected){assertEquals("A Download Station most nem érhető el. A korábbi lista megmaradt.",expected.getMessage());}assertEquals(3,f.requests.get());}}
 @Test public void explicitRejectionKeepsItsExceptionType()throws Exception{try(Fixture f=new Fixture()){NasClient client=f.client();f.rejectCode=105;try{request(client,false,new byte[]{1});fail();}catch(NasClient.ApiRejectedException expected){assertTrue(expected.getMessage().contains("(105)"));}assertEquals(1,f.requests.get());}}
 @Test public void allSessionExpiryCodesRenewAndRetry()throws Exception{for(int code:new int[]{106,107,119})try(Fixture f=new Fixture()){NasClient client=f.client();f.expiredCode=code;assertTrue(request(client,true,null).getBoolean("ok"));assertEquals(2,f.requests.get());assertEquals(2,f.logins.get());}}
 @Test public void concurrentExpiredRequestsOnlyRenewOnce()throws Exception{try(Fixture f=new Fixture()){NasClient client=f.client();f.expiredCode=106;f.expiredPair=new CountDownLatch(2);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<JSONObject> first=pool.submit(()->request(client,true,null)),second=pool.submit(()->request(client,true,null));assertTrue(first.get(6,TimeUnit.SECONDS).getBoolean("ok"));assertTrue(second.get(6,TimeUnit.SECONDS).getBoolean("ok"));assertEquals(2,f.logins.get());assertEquals(4,f.requests.get());}finally{pool.shutdownNow();}}}
 @Test public void explicitSessionRejectionCanRetryWithoutDuplicatingSuccessfulWrite()throws Exception{try(Fixture f=new Fixture()){NasClient client=f.client();f.expiredCode=106;assertTrue(request(client,false,null).getBoolean("ok"));assertEquals(2,f.requests.get());assertEquals(2,f.logins.get());assertEquals(1,f.mutations.get());}}
 @Test public void reconnectionInstallsWithoutWaitingForUncertainUploadAndDoesNotReplayIt()throws Exception{
  try(Fixture f=new Fixture()){
   NasClient root=f.client();f.slowUpload=true;ExecutorService pool=Executors.newFixedThreadPool(2);
   try{
    Future<?> write=pool.submit(()->request(root,false,new byte[]{1,2,3}));assertTrue(f.uploadEntered.await(3,TimeUnit.SECONDS));
    int token=root.suspendConnection();NasClient next=pool.submit(()->root.reconnectCandidate(false)).get(3,TimeUnit.SECONDS);
    assertTrue(root.installConnection(token,next));assertFalse(write.isDone());
    assertArrayEquals(new byte[]{1,2,3},root.readFile("/video/movie.mkv",100));assertEquals(1,f.requests.get());
    f.release.countDown();write.get(3,TimeUnit.SECONDS);assertEquals(1,f.mutations.get());assertEquals(1,f.requests.get());
   }finally{f.release.countDown();pool.shutdownNow();}
  }
 }

 @Test public void slowFolderInventoryDoesNotBlockVideoUrlOrRead()throws Exception{try(Fixture f=new Fixture()){NasClient client=f.client();f.slowList=true;ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> scan=pool.submit(()->client.list("/video"));assertTrue(f.discoveryEntered.await(3,TimeUnit.SECONDS));Future<byte[]> video=pool.submit(()->client.readFile("/video/movie.mkv",100));assertArrayEquals(new byte[]{1,2,3},video.get(2,TimeUnit.SECONDS));assertFalse(scan.isDone());f.release.countDown();scan.get(3,TimeUnit.SECONDS);}finally{f.release.countDown();pool.shutdownNow();}}}

 @Test public void concurrentFolderExpiryRenewsOnlyOnceForEverySessionCode()throws Exception{for(int code:new int[]{106,107,119})try(Fixture f=new Fixture()){NasClient client=f.client();f.expiredCode=code;f.expiredPair=new CountDownLatch(2);ExecutorService io=Executors.newFixedThreadPool(2);try{Future<?> first=io.submit(()->client.list("/video")),second=io.submit(()->client.list("/video"));first.get(6,TimeUnit.SECONDS);second.get(6,TimeUnit.SECONDS);assertEquals(2,f.logins.get());}finally{io.shutdownNow();}}}

